// Normalize database so every player object has the exact upgraded schema
export const TEAM_SEASONS = RAW_TEAM_SEASONS.map((ts) => ({
    ...ts,
    players: ts.players.map((player, index) => ({
        id: `${ts.id}-${index}`,
        name: player.name,
        club: ts.club,
        year: ts.year,
        league: ts.league,
        positions: [...player.positions],
        overall: player.overall,
        attack: player.attack,
        creation: player.creation,
        defense: player.defense,
        physical: player.physical,
        goalkeeping: player.goalkeeping,
    })),
}));

// ---------- Structured Query Indexes ----------
// Guarantees that all rolls and rerolls only ever produce valid (league, club, year) combinations

export const TEAM_SEASON_MAP = new Map(TEAM_SEASONS.map((ts) => [ts.id, ts]));

export const LEAGUES = [];
export const CLUBS_BY_LEAGUE = new Map();       // league -> string[]
export const YEARS_BY_LEAGUE_CLUB = new Map();  // `${league}::${club}` -> number[]
export const TEAM_SEASON_BY_COMBO = new Map();  // `${league}::${club}::${year}` -> teamSeason

for (const ts of TEAM_SEASONS) {
    if (!LEAGUES.includes(ts.league)) {
        LEAGUES.push(ts.league);
    }

    if (!CLUBS_BY_LEAGUE.has(ts.league)) {
        CLUBS_BY_LEAGUE.set(ts.league, []);
    }
    const clubs = CLUBS_BY_LEAGUE.get(ts.league);
    if (!clubs.includes(ts.club)) {
        clubs.push(ts.club);
    }

    const lcKey = `${ts.league}::${ts.club}`;
    if (!YEARS_BY_LEAGUE_CLUB.has(lcKey)) {
        YEARS_BY_LEAGUE_CLUB.set(lcKey, []);
    }
    const years = YEARS_BY_LEAGUE_CLUB.get(lcKey);
    if (!years.includes(ts.year)) {
        years.push(ts.year);
    }

    TEAM_SEASON_BY_COMBO.set(`${ts.league}::${ts.club}::${ts.year}`, ts);
}

export function getLeagues() {
    return LEAGUES;
}

export function getClubsByLeague(league) {
    return CLUBS_BY_LEAGUE.get(league) ?? [];
}

export function getYearsByLeagueAndClub(league, club) {
    return YEARS_BY_LEAGUE_CLUB.get(`${league}::${club}`) ?? [];
}

export function findTeamSeason(league, club, year) {
    return TEAM_SEASON_BY_COMBO.get(`${league}::${club}::${year}`) ?? null;
}
